ARABIC_DIGITS = str.maketrans('0123456789', '٠١٢٣٤٥٦٧٨٩')
pages = []
figure_number = 0

@contextmanager
def local_document():
    class QuietHandler(SimpleHTTPRequestHandler):
        def log_message(self, *args):
            pass
    server = ThreadingHTTPServer(('127.0.0.1', 0), partial(QuietHandler, directory=str(DOC)))
    thread = Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        yield 'http://127.0.0.1:' + str(server.server_port) + '/manual.html'
    finally:
        server.shutdown()
        server.server_close()
        thread.join(timeout=5)

def ar(number):
    return str(number).translate(ARABIC_DIGITS)

def code(value):
    return '<span class="code">' + html.escape(value) + '</span>'

def amount(value):
    return '<span class="amount">' + str(value) + '</span>'

def note(title, text, kind=''):
    return f'<aside class="note {kind}"><b>{title}</b> · {text}</aside>'

def steps(items, compact=False):
    return '<ol class="steps '+('compact' if compact else '')+'">'+''.join(
        f'<li><span class="step-n">{ar(i)}</span><div><b>{title}</b><p>{text}</p></div></li>'
        for i, (title, text) in enumerate(items, 1))+'</ol>'

def flow(items):
    return '<ol class="flow">'+''.join(f'<li><b>{title}</b><span>{text}</span></li>' for title,text in items)+'</ol>'

def shot(name, caption, kind='', label=''):
    global figure_number
    figure_number += 1
    return f'''<figure><div class="screenshot {kind}">{'<span class="screen-label">'+label+'</span>' if label else ''}<img src="assets/{name}.png" alt="{html.escape(caption)}"></div><figcaption><span class="fig-num">شكل {ar(figure_number)}</span><span>{caption}<span class="caption-tail">بيانات خيالية للتجربة.</span></span></figcaption></figure>'''

def table(headings, rows, klass=''):
    return '<table class="'+klass+'"><thead><tr>'+''.join('<th>'+value+'</th>' for value in headings)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+value+'</td>' for value in row)+'</tr>' for row in rows)+'</tbody></table>'

def page(chapter, title, intro, content, short=None):
    pages.append({'chapter': chapter, 'title':title, 'intro':intro, 'content':content, 'short':short or title})

