def cover():
    return '''<section class="sheet cover" id="page-1"><div class="cover-side"><span class="cover-side-kicker">WASH / MAREB</span><svg class="cover-network" viewBox="0 0 260 650" aria-hidden="true"><g fill="none" stroke="#77b9b7" stroke-width="1.3"><path d="M34 20v90h84v80h88v102H72v112h132v83H38v140"/><path d="M226 0v58H168v88H36v110h119v101H28v110h110v172"/><path d="M88 0v62h42v90h108v84h-46v164h45v110h-74v125"/></g><g fill="#16384a" stroke="#e0bd91" stroke-width="2.5"><circle cx="118" cy="110" r="8"/><circle cx="206" cy="190" r="8"/><circle cx="72" cy="292" r="8"/><circle cx="204" cy="404" r="8"/><circle cx="38" cy="487" r="8"/><circle cx="36" cy="146" r="8"/><circle cx="155" cy="256" r="8"/><circle cx="28" cy="357" r="8"/><circle cx="138" cy="467" r="8"/></g><g stroke="#fff" opacity=".12"><path d="M0 570h260M0 595h260M0 620h260M30 540v110M65 540v110M100 540v110M135 540v110M170 540v110M205 540v110M240 540v110"/></g></svg><div class="cover-side-note">USER GUIDE<br>COMMITTEE EVALUATION<br><br>AR / 1.0<br>07 OCT 2026</div></div><div class="cover-main"><div class="institution"><img src="assets/logo.png" alt="شعار المؤسسة"><div><b>المؤسسة العامة للمياه<br>والصرف الصحي</b><br>فرع مأرب</div></div><p class="cover-kicker">مرجع الاستخدام واستعراض النسخة التجريبية</p><h1>دليل المستخدم<br>واستعراض النظام</h1><p class="subtitle">نظام إدارة بلاغات المستفيدين<br>والمخالفات الميدانية</p><div class="cover-line"></div><p class="muted">خطوات واضحة، ومسارات موثقة،<br>وصور فعلية من واجهات النظام.</p><div class="cover-credit">معد النظام<strong>حسن القشائي</strong></div><div class="cover-metadata">الإصدار1.0 للدليل<br>7 أكتوبر2026</div></div><div class="cover-version"><b>نسخة مخصصة لتقييم اللجنة</b>بيانات الصور خيالية · ليست وثيقة اعتماد مؤسسي</div></section>'''

def render_html():
    total=len(pages)
    sections=[]
    for i,item in enumerate(pages,1):
        if item.get('cover'):
            sections.append(cover()); continue
        if item.get('toc'):
            left=[];right=[]
            for n,p in enumerate(pages,1):
                if n<4: continue
                link=f'<li><a href="#page-{n}"><span>{p["title"]}</span><span class="toc-n">{ar(n)}</span></a></li>'
                (right if n<=14 else left).append(link)
            content='<div class="two-col"><ul class="contents">'+''.join(right)+'</ul><ul class="contents">'+''.join(left)+'</ul></div>'+note('تنقل مباشر','فهرس PDF تفاعلي؛ اضغط عنوان القسم للوصول إلى صفحته. استخدم العلامات المرجعية في قارئ PDF إن كانت متاحة.','tip')
            intro='من فهم الأدوار إلى تنفيذ الإجراءات وتوثيق تقييم اللجنة.'
            chapter='01'
        else:
            content=item['content'];intro=item['intro'];chapter=item['chapter']
        sections.append(f'''<section class="sheet" id="page-{i}" aria-label="{html.escape(item['title'])}"><header class="header"><div class="brand"><img src="assets/logo.png" alt=""><div><b>مياه مأرب</b><span>دليل المستخدم واستعراض النظام</span></div></div><div class="doccode">WASH / UG–AR / 1.0<br>07 OCT 2026</div></header><div class="page-content"><div class="eyebrow">القسم {ar(chapter)} / النسخة التجريبية</div><span class="section-no">{chapter}</span><h1>{item['title']}</h1><p class="intro">{intro}</p><div class="rule"></div>{content}</div><footer class="footer"><span>المؤسسة العامة للمياه والصرف الصحي — فرع مأرب</span><span class="page-number">صفحة {ar(i)} من {ar(total)}</span></footer></section>''')
    result='<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>دليل المستخدم — مياه مأرب | حسن القشائي</title><link rel="stylesheet" href="styles.css"></head><body>'+''.join(sections)+'</body></html>'
    for old,new in [('5ميجابايت','5 ميجابايت'),('بنواة64بت','بنواة 64 بت'),('الإصدار1.0','الإصدار 1.0'),('إصدار1.0','إصدار 1.0'),('أكتوبر2026','أكتوبر 2026'),('10.5م³','10.5 م³'),('إجمالي329,200ريال','إجمالي 329,200 ريال')]:
        result=result.replace(old,new)
    return result

def main():
    OUT.mkdir(parents=True,exist_ok=True)
    (DOC/'assets').mkdir(exist_ok=True)
    for source in SOURCE_ASSETS.glob('*.png'):
        shutil.copyfile(source,DOC/'assets'/source.name)
    license_source=ROOT/'static/fonts/LICENSE.txt'
    shutil.copyfile(license_source,DOC/'assets/FONT-LICENSE.txt')
    compose()
    target=DOC/'manual.html'
    target.write_text(render_html(),encoding='utf-8')
    with local_document() as document_url, sync_playwright() as playwright:
        browser=playwright.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
        context=browser.new_context(viewport={'width':1000,'height':1200},device_scale_factor=1.5)
        page=context.new_page()
        page.goto(document_url,wait_until='networkidle')
        page.evaluate('document.fonts.ready')
        errors=page.evaluate('''() => { const errors=[]; document.querySelectorAll('.sheet').forEach((sheet,i)=> { const content=sheet.querySelector('.page-content'); const footer=sheet.querySelector('.footer'); if(content && content.getBoundingClientRect().bottom > footer.getBoundingClientRect().top-10) errors.push({page:i+1,overflow:content.getBoundingClientRect().bottom-footer.getBoundingClientRect().top+10}); }); for(const img of document.images) if(!img.complete || !img.naturalWidth) errors.push({image:img.getAttribute('src')}); return errors; }''')
        (OUT/'layout-check.json').write_text(json.dumps({'pages':len(pages),'errors':errors},indent=2))
        if errors:
            browser.close()
            raise RuntimeError('Layout/images need correction: '+json.dumps(errors))
        for n in (1,3,8,12,18,19,24,25):
            page.locator(f'#page-{n}').screenshot(path=str(OUT/f'preview-{n:02}.png'))
        page.pdf(path=str(PDF),print_background=True,prefer_css_page_size=True,tagged=True,outline=True)
        browser.close()
    document=fitz.open(PDF)
    assert len(document)==len(pages), (len(document),len(pages))
    metadata=document.metadata
    metadata.update(title='دليل المستخدم واستعراض النظام — مياه مأرب', author='حسن القشائي',subject='دليل عربي مصور لتقييم نظام بلاغات المستفيدين والمخالفات الميدانية',keywords='مياه مأرب، دليل المستخدم، حسن القشائي، بلاغات المستفيدين، المخالفات')
    document.set_metadata(metadata)
    toc=[[1, p['title'], i] for i,p in enumerate(pages,1)]
    document.set_toc(toc)
    temporary=PDF.with_suffix('.tmp.pdf')
    document.save(temporary,garbage=4,deflate=True)
    document.close()
    temporary.replace(PDF)
    with PDF.open('rb') as file:
        checksum=hashlib.file_digest(file,'sha256').hexdigest()
    PDF.with_suffix('.sha256').write_text(checksum+'  '+PDF.name+'\n')
    result={'pdf':str(PDF),'pages':len(pages),'figures':figure_number,'bytes':PDF.stat().st_size,'sha256':checksum,'author':'حسن القشائي','layout_errors':errors}
    (OUT/'build-result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
    print(json.dumps(result,ensure_ascii=False))

if __name__=='__main__':
    main()
